package org.oagi.score.gateway.http.api.bie_management.service.generate_expression;

import java.io.File;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.function.Supplier;
import java.util.function.UnaryOperator;

/**
 * Keeps the components that the files of one generation request share. Each file is generated by an expression
 * instance of its own, and the host puts the same registry into the {@link GenerationContext} of all of them, so that
 * what every file would repeat (for XML Schema, the global declarations of the code lists) is dealt with once for
 * the request.
 */
public class SharedComponentRegistry {

    private record Entry(Object components, Supplier<List<File>> asFiles) {
    }

    private final UnaryOperator<String> sharedFilenameResolver;
    private final Map<String, String> sharedFilenames = new LinkedHashMap<>();
    private final Map<Object, Entry> entries = new LinkedHashMap<>();

    /**
     * @param sharedFilenameResolver gives the base filename (without file extension) of a shared file from its name,
     *                               different from the filename of any other file
     */
    public SharedComponentRegistry(UnaryOperator<String> sharedFilenameResolver) {
        this.sharedFilenameResolver = sharedFilenameResolver;
    }

    /**
     * The base filename (without file extension) of a shared file. A file, known by its identity, gets the same
     * filename each time; the name is what the filename is made from, and two files can have the same name.
     */
    synchronized String sharedFilename(String identity, String name) {
        return sharedFilenames.computeIfAbsent(identity, k -> sharedFilenameResolver.apply(name));
    }

    /**
     * Returns the shared components kept under the key, or creates them.
     *
     * @param asFiles writes the files of the components when the request is generated, throws
     *                {@link UncheckedIOException} on failure
     */
    @SuppressWarnings("unchecked")
    synchronized <T> T sharedComponents(Object key, Supplier<T> factory, Function<T, List<File>> asFiles) {
        return (T) entries.computeIfAbsent(key, k -> {
            T components = factory.get();
            return new Entry(components, () -> asFiles.apply(components));
        }).components();
    }

    /**
     * Finishes the shared components of the request, and returns the files that they make besides the files of the
     * request, which are none when nothing needs a file of its own.
     */
    public synchronized List<File> asFiles() throws IOException {
        List<File> files = new ArrayList<>();
        try {
            for (Entry entry : entries.values()) {
                files.addAll(entry.asFiles().get());
            }
        } catch (UncheckedIOException e) {
            throw e.getCause();
        }
        return files;
    }
}
